import sys

def main():
    lines = []
    for line in sys.stdin:
        stripped = line.strip()
        if stripped:
            lines.append(stripped)

    if not lines:
        print(-1)
        return

    try:
        base = int(lines[0])
    except (ValueError, IndexError):
        print(-1)
        return

    bonus = 0
    deductions = 0

    if len(lines) >= 2:
        try:
            bonus = int(lines[1])
        except ValueError:
            bonus = 0

    if len(lines) >= 3:
        try:
            deductions = int(lines[2])
        except ValueError:
            deductions = 0

    result = base + bonus - deductions
    print(result)

if __name__ == "__main__":
    main()
